import{_ as t,o as i,c as a,ae as n}from"./chunks/framework.DQC_QtFV.js";const p=JSON.parse('{"title":"Disclaimer","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/disclaimer.md","filePath":"en/guide/disclaimer.md","lastUpdated":1793162416000}'),o={name:"en/guide/disclaimer.md"};function s(r,e,l,d,c,h){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="disclaimer" tabindex="-1">Disclaimer <a class="header-anchor" href="#disclaimer" aria-label="Permalink to &quot;Disclaimer&quot;">​</a></h1><p>The full text is the repository&#39;s <a href="https://github.com/4fuu/personal-bot/blob/main/DISCLAIMER.md" target="_blank" rel="noreferrer">DISCLAIMER.md</a>; this page is its substance. Read the full file before you run anything.</p><h2 id="not-affiliated-with-tencent" tabindex="-1">Not affiliated with Tencent <a class="header-anchor" href="#not-affiliated-with-tencent" aria-label="Permalink to &quot;Not affiliated with Tencent&quot;">​</a></h2><p>personal-bot is an independent, third-party interoperability project. It has <strong>no affiliation, partnership, authorisation or endorsement relationship with Tencent or with QQ</strong>, and it is not an official Tencent product. &quot;QQ&quot;, &quot;Tencent&quot; and related marks belong to their respective owners. Nothing here is provided, reviewed or approved by Tencent.</p><h2 id="what-it-does-plainly" tabindex="-1">What it does, plainly <a class="header-anchor" href="#what-it-does-plainly" aria-label="Permalink to &quot;What it does, plainly&quot;">​</a></h2><p>The stack runs the <strong>official, unmodified QQ NT desktop client for Linux</strong> inside a container, on a virtual display, and does three things with that client:</p><ul><li>it reads messages out of a <strong>private, decrypted copy</strong> of the client&#39;s own local database, which never leaves your machine;</li><li>it sends messages by calling the client&#39;s <strong>own send function</strong> through a small library the container preloads into the client at launch - no file of the client is patched, replaced or written to;</li><li>it clicks the client&#39;s own 登录 button over the accessibility bus when the client returns to its account page, so a saved session resumes on its own. A QR login stays manual, and it is yours to do.</li></ul><p>It reads nothing else. It does not read your contacts beyond the names the client itself shows, it does not listen to any event stream of the client, and it sends nothing anywhere except the model provider you configure and the MCP servers you connect.</p><h2 id="the-risk-is-yours" tabindex="-1">The risk is yours <a class="header-anchor" href="#the-risk-is-yours" aria-label="Permalink to &quot;The risk is yours&quot;">​</a></h2><p>Automating a chat client is outside that client&#39;s terms of service. The account you run this with can be <strong>restricted, suspended or permanently lost</strong>, and your local message history can be lost with it. That risk is yours, and you take it on voluntarily.</p><p>To keep it as small as it can be:</p><ul><li>use a secondary account that already has some history, not a fresh one;</li><li>run on a residential connection, not a datacenter IP;</li><li>keep the default send pacing, and do not raise it;</li><li>keep the client&#39;s own version, and do not let it update itself.</li></ul><h2 id="provided-as-is" tabindex="-1">Provided as is <a class="header-anchor" href="#provided-as-is" aria-label="Permalink to &quot;Provided as is&quot;">​</a></h2><p>This project is provided <strong>as is</strong> and <strong>as available</strong>, without warranty of any kind, express or implied, including merchantability, fitness for a particular purpose, non-infringement, availability, accuracy or uninterrupted operation. To the maximum extent permitted by law, the authors and copyright holders are not liable for any direct, indirect, incidental, special, punitive or consequential damage - including account restriction or loss, data loss, lost profits or business, or service interruption - arising from the use of, or the inability to use, this project.</p><h2 id="no-unlawful-use" tabindex="-1">No unlawful use <a class="header-anchor" href="#no-unlawful-use" aria-label="Permalink to &quot;No unlawful use&quot;">​</a></h2><p>You may not use this project for any unlawful purpose, including spam, harassment, fraud, unauthorised access to any system or network, or the distribution of malicious content. You are responsible for making sure your use complies with the laws that apply to you and with the terms of every platform you connect.</p>',16)])])}const f=t(o,[["render",s]]);export{p as __pageData,f as default};
